"use strict";(self.webpackChunkow_ui=self.webpackChunkow_ui||[]).push([[8749],{91895:n=>{n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/2025/03/08/optimal-docs-tool-choice","metadata":{"permalink":"/blog/2025/03/08/optimal-docs-tool-choice","source":"@site/blog/2025-03-08-optimal-docs-tool-choice.md","title":"\u5225\u518d\u627e\u6587\u4ef6\u64b0\u5beb\u5de5\u5177\u4e86\uff1f\u5b78\u6703\u9019\u500b\u638c\u63e1\u6587\u4ef6\u6e05\u6670\u5ea6\uff01","description":"\u5982\u4f55\u9078\u64c7\u6700\u9069\u5408\u7684\u6587\u4ef6\u64b0\u5beb\u5de5\u5177\uff1f\u672c\u7bc7\u6587\u7ae0\u63a2\u8a0e\u6587\u4ef6\u53ef\u8b80\u6027\u8207\u6d41\u66a2\u5ea6\u7684\u6838\u5fc3\uff0c\u63d0\u4f9b\u8edf\u9ad4\u5de5\u7a0b\u5e2b\u3001\u5c08\u6848\u7d93\u7406\u3001\u7522\u54c1\u7d93\u7406\u8207\u7cfb\u7d71\u5206\u6790\u5e2b (SA) \u6700\u4f73\u6587\u4ef6\u64b0\u5beb\u7b56\u7565\uff0c\u63d0\u5347\u6548\u7387\u8207\u6e05\u6670\u5ea6\u3002","date":"2025-03-08T00:00:00.000Z","tags":[],"readingTime":7.986666666666666,"hasTruncateMarker":true,"authors":[{"name":"Lucy","title":"Co-Founder of SAD-AI","url":"https://github.com/sad-ai-online","imageURL":"https://avatars.githubusercontent.com/u/74943742?v=4","key":"lucy","page":null}],"frontMatter":{"date":"2025-03-08T00:00:00.000Z","title":"\u5225\u518d\u627e\u6587\u4ef6\u64b0\u5beb\u5de5\u5177\u4e86\uff1f\u5b78\u6703\u9019\u500b\u638c\u63e1\u6587\u4ef6\u6e05\u6670\u5ea6\uff01","authors":["lucy"],"description":"\u5982\u4f55\u9078\u64c7\u6700\u9069\u5408\u7684\u6587\u4ef6\u64b0\u5beb\u5de5\u5177\uff1f\u672c\u7bc7\u6587\u7ae0\u63a2\u8a0e\u6587\u4ef6\u53ef\u8b80\u6027\u8207\u6d41\u66a2\u5ea6\u7684\u6838\u5fc3\uff0c\u63d0\u4f9b\u8edf\u9ad4\u5de5\u7a0b\u5e2b\u3001\u5c08\u6848\u7d93\u7406\u3001\u7522\u54c1\u7d93\u7406\u8207\u7cfb\u7d71\u5206\u6790\u5e2b (SA) \u6700\u4f73\u6587\u4ef6\u64b0\u5beb\u7b56\u7565\uff0c\u63d0\u5347\u6548\u7387\u8207\u6e05\u6670\u5ea6\u3002","keywords":["\u6587\u4ef6\u64b0\u5beb\u5de5\u5177","\u6587\u4ef6\u7ba1\u7406","\u6280\u8853\u6587\u4ef6","\u8edf\u9ad4\u958b\u767c\u6587\u6a94","\u5c08\u6848\u7ba1\u7406","\u7522\u54c1\u6587\u4ef6","\u6587\u4ef6\u53ef\u8b80\u6027","\u64b0\u5beb\u6280\u5de7","\u6587\u4ef6\u6392\u7248","\u6280\u8853\u6e9d\u901a","\u9700\u6c42\u6587\u4ef6","\u6587\u4ef6\u683c\u5f0f"]},"unlisted":false,"nextItem":{"title":"\u6c92\u6709\u6280\u8853\u80cc\u666f\uff1f\u5e36\u4f60\u5beb\u51fa\u6e05\u6670\u6613\u61c2\u7684\u9700\u6c42\u6587\u4ef6","permalink":"/blog/2025/03/02/write-requirements-without-tech"}},"content":"\u5982\u4f55\u9078\u64c7\u6700\u9069\u5408\u7684\u6587\u4ef6\u64b0\u5beb\u5de5\u5177\uff1f\u672c\u7bc7\u6587\u7ae0\u63a2\u8a0e\u6587\u4ef6\u53ef\u8b80\u6027\u8207\u6d41\u66a2\u5ea6\u7684\u6838\u5fc3\uff0c\u63d0\u4f9b\u8edf\u9ad4\u5de5\u7a0b\u5e2b\u3001\u5c08\u6848\u7d93\u7406\u3001\u7522\u54c1\u7d93\u7406\u8207\u7cfb\u7d71\u5206\u6790\u5e2b (SA) \u6700\u4f73\u6587\u4ef6\u64b0\u5beb\u7b56\u7565\uff0c\u63d0\u5347\u6548\u7387\u8207\u6e05\u6670\u5ea6\u3002\\n\\n\x3c!-- truncate --\x3e\\n\\n## \u524d\u8a00\\n\\n\u5728\u6280\u8853\u6587\u4ef6\u64b0\u5beb\u4e2d\uff0c\u9078\u64c7\u5408\u9069\u7684\u5de5\u5177\u4e26\u975e\u95dc\u9375\uff0c\u771f\u6b63\u5f71\u97ff\u54c1\u8cea\u7684\u662f**\u5167\u5bb9\u7d50\u69cb\u8207\u8868\u9054\u80fd\u529b**\u3002\\n\\n\u8a31\u591a\u4eba\u7cfe\u7d50\u65bc\u300c\u54ea\u500b\u6587\u4ef6\u5de5\u5177\u6700\u597d\u300d\uff0c\u4f46\u5be6\u969b\u4e0a\uff0c**\u6700\u9069\u5408\u7684\u5f80\u5f80\u662f\u81ea\u5df1\u6700\u719f\u6089\u3001\u6700\u9806\u624b\u7684\u90a3\u500b\u3002**\\n\\n\u6280\u8853\u6587\u4ef6\u7684\u53ef\u8b80\u6027\u8207\u6d41\u66a2\u5ea6\uff0c\u6c7a\u5b9a\u65bc\u4e09\u500b\u95dc\u9375\u56e0\u7d20\uff1a\\n\\n<br />\\n\\n\u2705 \u5167\u5bb9\u638c\u63e1\u5ea6 \u2013 \u4f5c\u8005\u5c0d\u4e3b\u984c\u7684\u7406\u89e3\u7a0b\u5ea6\uff0c\u6c7a\u5b9a\u4e86\u6587\u4ef6\u7684\u6e05\u6670\u5ea6\u3002\\n\\n\u2705 \u908f\u8f2f\u8207\u7d50\u69cb \u2013 \u80fd\u5426\u8b93\u8b80\u8005\u9806\u66a2\u5730\u7406\u89e3\uff0c\u800c\u4e0d\u88ab\u904e\u591a\u6216\u904e\u5c11\u7684\u8cc7\u8a0a\u5e72\u64fe\uff1f\\n\\n\u2705 \u6587\u5b57\u7d44\u7e54\u80fd\u529b \u2013 \u5982\u4f55\u7528\u6700\u7c21\u6f54\u7684\u65b9\u5f0f\uff0c\u628a\u8907\u96dc\u6982\u5ff5\u8b1b\u6e05\u695a\uff1f\\n\\n<br />\\n\\n\u7576\u4f60\u5c0d\u5167\u5bb9\u6709 100% \u7684\u7406\u89e3\uff0c\u4e26\u80fd\u689d\u7406\u6e05\u6670\u5730\u8868\u9054\uff0c\u8b80\u8005\u5c31\u80fd\u300c\u79d2\u61c2\u300d\uff0c\u7121\u9700\u4f86\u56de\u78ba\u8a8d\u7d30\u7bc0\u3002\\n\\n> \u6587\u4ef6\u64b0\u5beb\u7684\u6838\u5fc3\u4e0d\u662f\u5de5\u5177\uff0c\u800c\u662f\u80fd\u5426\u6e05\u695a\u8868\u9054\u60f3\u8aaa\u7684\u8a71\u3002\\n\\n<br />\\n\\n\u958b\u767c\u904e\u7a0b\u4e2d\uff0c\u6587\u4ef6\u5167\u5bb9\u7684\u9846\u7c92\u5ea6\u6c7a\u5b9a\u4e86\u958b\u767c\u7684\u901f\u5ea6\uff0c\u56e0\u70ba\u9b54\u9b3c\u51fa\u5728\u7d30\u7bc0\u88e1\u3002\\n\\n\u8209\u4f8b\u4f86\u8aaa\uff1a\\n\\n```\\n\u7531\u65bc XX \u653f\u7b56\u958b\u653e\uff0c\u884c\u92b7\u90e8\u9580\u5e0c\u671b\u63d0\u4f9b OO \u529f\u80fd\uff0c\\n\\n\u8b93\u767b\u5165\u7528\u6236\u80fd\u5920\u5728\u9996\u9801\u4e0a\u5feb\u901f\u627e\u5230\u8a72\u529f\u80fd\uff0c\u9032\u4e00\u6b65\u63d0\u5347\u7522\u54c1\u66dd\u5149\u7387\u8207\u8f49\u5316\u7387\u3002\\n\\n- \u529f\u80fd\u6d41\u7a0b\\n\\n1.\u767b\u5165\u5f8c\u9996\u9801\u5c55\u793a\\n\\n  - \u5728\u767b\u5165\u5f8c\u7684\u9996\u9801\u4e0a\uff0c\u65b0\u589e OO \u529f\u80fd\u7684\u5165\u53e3\uff08\u4f8b\u5982\u6309\u9215\u6216 Banner\uff09\uff0c\\n  \u4f4d\u7f6e\u70ba [\u6307\u5b9a\u5340\u584a\uff0c\u6216\u53ef\u8abf\u6574]\u3002\\n\\n  - \u5141\u8a31\u884c\u92b7\u90e8\u9580\u900f\u904e\u5f8c\u53f0\u4e0a\u50b3 \u884c\u92b7\u6587\u6848\u8207\u63a8\u85a6\u7522\u54c1\uff0c\\n  \u53ef\u6839\u64da\u4e0d\u540c\u7528\u6236\u985e\u578b\uff08\u5982\u65b0\u5ba2 vs. \u820a\u5ba2\uff09\u52d5\u614b\u8abf\u6574\u5167\u5bb9\u3002\\n\\n2. \u529f\u80fd\u9801\uff08\u7522\u54c1\u6e05\u55ae\uff09\\n\\n  - \u9ede\u64ca\u9996\u9801\u5165\u53e3\u5f8c\uff0c\u9032\u5165 \u7522\u54c1\u6e05\u55ae\u9801\uff0c\u53ef\u700f\u89bd \u6240\u6709\u53ef\u8cfc\u8cb7\u7522\u54c1\u3002\\n  - \u7522\u54c1\u8cc7\u8a0a\u5305\u542b\uff1a\u540d\u7a31\u3001\u5716\u7247\u3001\u50f9\u683c\u3001\u7c21\u8981\u63cf\u8ff0\u3002\\n  - \u53ef\u900f\u904e \u5206\u985e\u7be9\u9078 / \u641c\u5c0b \u627e\u5230\u7279\u5b9a\u7522\u54c1\uff08\u5982\u9069\u7528\uff09\u3002\\n\\n3. \u7522\u54c1\u660e\u7d30\\n\\n  - \u9ede\u64ca\u7522\u54c1\u5f8c\uff0c\u9032\u5165 \u7522\u54c1\u8a73\u60c5\u9801\uff0c\u986f\u793a\u5b8c\u6574\u7684\u7522\u54c1\u8cc7\u8a0a\uff0c\u5305\u62ec\uff1a\\n    - \u8a73\u7d30\u898f\u683c\\n    - \u53ef\u8cfc\u8cb7\u6578\u91cf\u8207\u9078\u9805\\n    - \u4fc3\u92b7\u8cc7\u8a0a\uff08\u5982\u6709\uff09\\n\\n4. \u8cfc\u8cb7\u6d41\u7a0b\\n\\n  - \u5728\u7522\u54c1\u8a73\u60c5\u9801\uff0c\u4f7f\u7528\u8005\u9ede\u64ca ZZ \u6309\u9215\uff0c\u9032\u5165\u8cfc\u8cb7\u6d41\u7a0b\u3002\\n  - \u8cfc\u8cb7\u6d41\u7a0b\u6b65\u9a5f\u5305\u62ec\uff1a\\n    - \u9078\u64c7\u6578\u91cf\u8207\u898f\u683c\\n    - \u52a0\u5165\u8cfc\u7269\u8eca\uff08\u6216\u76f4\u63a5\u7d50\u5e33\uff09\\n    - \u4ed8\u6b3e\u65b9\u5f0f\u9078\u64c7\u8207\u7d50\u5e33\\n    - \u884c\u92b7\u8207\u6578\u64da\u7d00\u9304\\n\\n- \u884c\u92b7\u5167\u5bb9\u7ba1\u7406\uff1a\u5f8c\u53f0\u9700\u63d0\u4f9b\u4ecb\u9762\uff0c\u8b93\u884c\u92b7\u90e8\u9580\u53ef \u5f48\u6027\u4e0a\u4e0b\u67b6\u6587\u6848\u8207\u7522\u54c1\u3002\\n- \u6578\u64da\u8a18\u9304\uff08\u884c\u70ba\u5206\u6790\uff09\uff1a\u9700\u8a18\u9304 \u7528\u6236\u505c\u7559\u6642\u9593\u3001\u9ede\u64ca\u6b21\u6578\u3001\u8cfc\u8cb7\u8f49\u5316\u7387\uff0c\u4e26\u53ef\u65bc\u5f8c\u53f0\u67e5\u770b \u5831\u8868 / \u6578\u64da\u8996\u89ba\u5316\u3002\\n```\\n\\n\u76f8\u8f03\u65bc\\n\\n```\\n\u56e0\u61c9\u653f\u7b56\u6539\u8b8a\uff0c\u884c\u92b7\u90e8\u9580\u5e0c\u671b\u767b\u5165\u5f8c\u80fd\u6709\u76f8\u95dc\u529f\u80fd\uff0c\u65b9\u4fbf\u4f7f\u7528\u8005\u64cd\u4f5c\u3002\\n\\n\u9032\u5165\u5f8c\u53ef\u4ee5\u770b\u5230\u7522\u54c1\uff0c\u7136\u5f8c\u53ef\u4ee5\u9ede\u64ca\u67e5\u770b\u7d30\u7bc0\uff0c\u6700\u5f8c\u53ef\u4ee5\u8cfc\u8cb7\u3002\\n\\n\u9019\u500b\u6d41\u7a0b\u8981\u80fd\u5920\u652f\u63f4\u4e0d\u540c\u7684\u5167\u5bb9\u8abf\u6574\uff0c\u4e26\u4e14\u53ef\u4ee5\u8a18\u9304\u4f7f\u7528\u8005\u884c\u70ba\uff0c\u8b93\u5f8c\u53f0\u80fd\u67e5\u770b\u6578\u64da\u3002\\n```\\n\\n<br />\\n\\n\u4ee5\u4e0a\u5169\u500b\u7248\u672c\uff0c\u6703\u5f71\u97ff\u6280\u8853\u55ae\u4f4d\u8a55\u4f30\u9700\u6c42\u7684\u56de\u61c9\u901f\u5ea6\u3002\\n\\n<br />\\n\\n\u524d\u8005\uff0c\u8868\u793a\u696d\u52d9\u55ae\u4f4d\u5f88\u719f\u6089\u9810\u671f\u9a57\u8b49\u5167\u5bb9\uff0c\u4ee5\u53ca\u696d\u52d9\u7b56\u7565\u8003\u91cf\u3002\\n\\n\u5f8c\u8005\uff0c\u53ea\u63cf\u8ff0\u4e86\u5e0c\u671b\u7684\u7d50\u679c\uff0c\u4f46\u904e\u7a0b\u4e2d\u8a31\u591a\u7d30\u7bc0\u4e26\u672a\u63d0\u5230\uff0c\u5c31\u6703\u9700\u8981\u9032\u4e00\u6b65\u5c0d\u7126\u6587\u5b57\u80cc\u5f8c\u7684\u8003\u91cf\u3002\\n\\n<br />\\n\\n\u7b46\u8005\u8a8d\u70ba\u983b\u7e41\u7684\u6e9d\u901a\u662f\u5fc5\u9808\u7684\uff0c\u4f46\u91cd\u8981\u7684\u662f\uff0c\u9700\u6c42\u8005\u8981\u6e05\u695a\u77e5\u9053\u9810\u671f\u7d50\u679c\uff0c\u4ee5\u53ca\u662f\u5426\u7b26\u5408\u5546\u696d\u7b56\u7565\u3002\\n\\n> \u5c0d\u7126\u662f\u70ba\u4e86\u6253\u9020\u66f4\u597d\u7684\u7522\u54c1\uff01\\n\\n<br />\\n\\n\u63a5\u4e0b\u4f86\uff0c\u6211\u5011\u4e00\u8d77\u4f86\u770b\u770b\u64b0\u5beb\u6587\u4ef6\u8981\u6ce8\u610f\u54ea\u4e9b\uff01\\n\\n<br />\\n\\n## \u64b0\u5beb\u6587\u4ef6\u7684\u8ff7\u601d\\n\\n\u5982\u679c\u4f60\u66fe\u7d93\u5617\u8a66\u904e\u591a\u7a2e\u6587\u4ef6\u7ba1\u7406\u8207\u5354\u4f5c\u5de5\u5177\uff0c\u5982 Notion, Obsidian, Confluence, Markdown, Google Docs \u6216 Word\uff0c\u6700\u7d42\u537b\u4ecd\u56de\u5230\u6700\u719f\u6089\u7684\u5de5\u5177\u3002\\n\\n\u90a3\u9ebc\u4f60\u61c9\u8a72\u7406\u89e3\uff1a**\u5de5\u5177\u53ea\u662f\u8f14\u52a9\uff0c\u5167\u5bb9\u624d\u662f\u95dc\u9375\u3002**\\n\\n<br />\\n\\n\ud83d\udccc \u8ff7\u601d 1\uff1a\u5de5\u5177\u6c7a\u5b9a\u6587\u4ef6\u54c1\u8cea\uff1f\\n\\n\u5f88\u591a\u4eba\u8a8d\u70ba\uff0c\u63db\u4e00\u500b\u5de5\u5177\uff0c\u5c31\u80fd\u5beb\u51fa\u66f4\u597d\u7684\u6587\u4ef6\u3002\u4f46\u5176\u5be6\uff0c**\u6700\u5f71\u97ff\u6587\u4ef6\u54c1\u8cea\u7684\u662f\u8868\u9054\u65b9\u5f0f\u3002**\\n\\n**\u5148\u5b78\u6703\u6709\u689d\u7406\u5730\u8868\u9054**\uff0c\u4e0d\u8ad6\u5728\u53e3\u8a9e\u6e9d\u901a\uff0c\u9084\u662f\u6587\u5b57\u8868\u8ff0\uff0c**\u5176\u6b21\u624d\u6b21\u5de5\u5177\u7684\u9078\u64c7\u3002**\\n\\n<br />\\n\\n\ud83d\udccc \u8ff7\u601d 2\uff1aMarkdown vs. Word\uff0c\u54ea\u500b\u66f4\u597d\uff1f\\n\\n\u9019\u53d6\u6c7a\u65bc\u9700\u6c42\uff0c\u53ef\u5f9e\u719f\u6089\u5ea6\u3001\u5718\u968a\u7fd2\u6163\u3001\u6587\u4ef6\u985e\u578b\u4f86\u6c7a\u5b9a\u3002\\n\\n\u5982\u679c\u5718\u968a\u7fd2\u6163\u4f7f\u7528 Markdown\uff0c\u90a3\u7576\u7136\u9078\u64c7 Markdown\uff0c\u4f46\u5982\u679c\u662f\u4ee5\u5546\u696d\u6587\u4ef6\u70ba\u4e3b\uff0c\u90a3 Word, Google Doc \u7684\u6392\u7248\u53ef\u80fd\u66f4\u76f4\u89c0\u3002\\n\\n\u5982\u679c\u6642\u7a0b\u5728\u524d\uff0c\u8981\u984d\u5916\u82b1\u6642\u9593\u5b78\u5de5\u5177\uff0c\u5c31\u4e0d\u662f\u6700\u597d\u7684\u9078\u64c7\u3002\\n\\n\u800c\u4e14\uff0c\u518d\u597d\u7684\u5de5\u5177\uff0c\u5718\u968a\u7528\u4e0d\u7fd2\u6163\uff0c\u4e5f\u7121\u6cd5\u767c\u63ee\u771f\u6b63\u7684\u6548\u76ca\u3002\\n\\n<br />\\n\\n\ud83d\udccc \u8ff7\u601d 3\uff1a\u9019\u6a23\u5beb\u61c9\u8a72\u5c31\u770b\u5f97\u61c2\u5427\uff01\\n\\n\u6709\u6642\u4f5c\u8005\u6703\u8ff7\u601d\u5728\u81ea\u5df1\u7684\u6846\uff0c\u5ffd\u7565\u8b80\u8005\u53ef\u80fd\u7b2c\u4e00\u6b21\u95b1\u8b80\u8a72\u5167\u5bb9\u3002\\n\\n<br />\\n\\n\u5c31\u50cf\u4f60\u525b\u7d44\u5b8c\u4e00\u500b\u8d85\u9177\u7684 IKEA \u6ac3\u5b50\uff0c\u8208\u596e\u5730\u8ddf\u670b\u53cb\u8aaa\uff1a\\n\\n> \u300c\u5f88\u7c21\u55ae\u554a\uff01\u5148\u9019\u6a23\uff0c\u518d\u90a3\u6a23\uff0c\u5c31\u597d\u4e86\uff01\u300d\\n\\n<br />\\n\u4f46\u670b\u53cb\u6eff\u982d\u554f\u865f\uff0c\u56e0\u70ba\u4ed6\u6839\u672c\u4e0d\u77e5\u9053\u300c\u9019\u6a23\u300d\u662f\u4ec0\u9ebc\u3001\u300c\u90a3\u6a23\u300d\u662f\u54ea\u6a23\u3002\\n\\n\u5c0d\u4f60\u4f86\u8aaa\uff0c\u6240\u6709\u6b65\u9a5f\u90fd\u7406\u6240\u7576\u7136\uff0c\u56e0\u70ba\u4f60\u525b\u525b\u624d\u89aa\u624b\u62fc\u6e4a\u51fa\u4f86\u3002\\n\\n<br />\\n\\n\u4f46\u5c0d\u7b2c\u4e00\u6b21\u63a5\u89f8\u7684\u8b80\u8005\u4f86\u8aaa\uff0c\u4ed6\u5011**\u6c92\u6709\u4f60\u7684\u5167\u5efa\u8a18\u61b6**\uff0c\u9700\u8981\u66f4\u591a\u80cc\u666f\u548c\u7d30\u7bc0\u624d\u80fd\u7406\u89e3\u4f60\u7684\u660e\u767d\uff01\\n\\n\u6240\u4ee5\uff0c\u5beb\u4f5c\u6642\u5225\u53ea\u60f3\u300c\u6211\u61c2\u4e86\u300d\uff0c\u800c\u8981\u63db\u500b\u89d2\u5ea6\u554f\uff1a**\u5982\u679c\u6211\u662f\u7b2c\u4e00\u6b21\u770b\u5230\u9019\u6bb5\u5167\u5bb9\u7684\u4eba\uff0c\u771f\u7684\u80fd\u770b\u61c2\u55ce\uff1f**\\n\\n<br />\\n\\n\u6700\u597d\u7684\u65b9\u5f0f\u662f\u5beb\u5b8c**\u8acb\u7b2c\u4e09\u8005\u95b1\u8b80**\uff0c\u5f9e\u4ed6\u5011\u7684\u53cd\u994b\u4e2d\u8abf\u6574\u7528\u5b57\u548c\u7de8\u6392\u3002\\n\\n\u5982\u679c\u5c0d\u65b9\u50cf\u662f\u5728\u89e3 IKEA \u8aaa\u660e\u66f8\uff0c\u90a3\u4e5f\u8a31\u8a72\u518d\u8abf\u6574\u4e00\u4e0b\u7528\u5b57\u548c\u7de8\u6392\u4e86 \ud83d\ude09\\n\\n\u7562\u7adf\uff0c\u597d\u7684\u5beb\u4f5c\u4e0d\u53ea\u662f\u8b93\u81ea\u5df1\u89ba\u5f97\u9806\uff0c\u800c\u662f\u8b93\u8b80\u8005\u4e0d\u7528**\u731c**\u3002\\n\\n<br />\\n\\n## \u5167\u5bb9\u638c\u63e1\u5ea6\uff1a\u4f60\u7684\u7406\u89e3\u7a0b\u5ea6\uff0c\u6c7a\u5b9a\u4e86\u8b80\u8005\u7684\u7406\u89e3\u7a0b\u5ea6\\n\\n\u662f\u5426\u66fe\u7d93\u8b80\u904e\u4e00\u7bc7\u6587\u4ef6\uff0c\u537b\u600e\u9ebc\u770b\u90fd\u89ba\u5f97\u4e0d\u660e\u6240\u4ee5\uff1f\u901a\u5e38\u662f\u56e0\u70ba\u4f5c\u8005\u6c92\u6709\u5b8c\u5168\u7406\u89e3\u5167\u5bb9\uff0c\u5c0e\u81f4\u5beb\u51fa\u4f86\u7684\u6587\u4ef6\u65e2\u4e0d\u6e05\u6670\uff0c\u4e5f\u7f3a\u4e4f\u689d\u7406\u3002\\n\\n\u5e38\u9047\u5230\uff0c\u5beb\u5b8c\u5f8c\u624d\u767c\u73fe\u908f\u8f2f\u4e0d\u901a\uff0c\u662f\u56e0\u70ba\u6c92\u6709\u4e8b\u5148\u898f\u5283\u6587\u7ae0\u7d50\u69cb\u3002\\n\\n\u6709\u6642\uff0c\u5beb\u4e86\u8207\u4e3b\u984c\u7121\u95dc\u7684\u7d30\u7bc0\uff0c\u66f4\u5bb9\u6613\u8b93\u8b80\u8005\u8ff7\u601d\u65b9\u5411\u3002\\n\\n\u53c8\u6216\u662f\u4e3b\u8a9e\u3001\u53d7\u8a5e\u3001\u8cd3\u8a9e\u8868\u8ff0\u4e0d\u6e05\u695a\uff0c\u4f7f\u5f97\u8b80\u8005\u7121\u6cd5\u7406\u89e3\u5b8c\u6574\u7684\u53e5\u5b50\u3002\\n\\n<br />\\n**\u90a3\u5982\u4f55\u63d0\u5347\u5167\u5bb9\u638c\u63e1\u5ea6\uff1f**\\n<br />\\n\\n\u5beb\u5f80\u5f80\u4e0d\u662f\u6700\u82b1\u6642\u9593\u7684\uff0c\u82b1\u6700\u591a\u6642\u9593\u662f\u7d44\u7e54\u8207\u67b6\u69cb\u5167\u5bb9\u7684\u6392\u5e8f\u3002\\n\\n\u5728\u52d5\u624b\u5beb\u6587\u4ef6\u524d\uff0c\u5148\u6574\u7406\u601d\u8def\uff0c\u78ba\u4fdd\u908f\u8f2f\u6e05\u695a\u3002\\n\\n\u5982\u679c\u80fd\u7528\u7c21\u55ae\u7684\u8a71\u8aaa\u660e\u6982\u5ff5\uff0c\u90a3\u5c31\u4ee3\u8868\u80fd\u7528\u6700\u63a5\u5730\u6c23\u7684\u8868\u9054\uff0c\u8b93\u8b80\u8005\u771f\u7684\u7406\u89e3\u3002\\n\\n\u7ad9\u5728\u8b80\u8005\u89d2\u5ea6\u601d\u8003\uff0c\u4f60\u7684\u8b80\u8005\u53ef\u80fd\u5c0d\u9019\u500b\u4e3b\u984c\u4e0d\u719f\u6089\uff0c\u4ed6\u5011\u9700\u8981\u54ea\u4e9b\u8cc7\u8a0a\uff1f\\n\\n<br />\\n\\n## \u6587\u5b57\u7d44\u7e54\u80fd\u529b\uff1a\u8b93\u8b80\u8005\u300c\u79d2\u61c2\u300d\u7684\u95dc\u9375\\n\\n\u597d\u7684\u6587\u4ef6\uff0c\u8981\u8b93\u8b80\u8005\u4e00\u773c\u5c31\u80fd\u6293\u5230\u91cd\u9ede\uff0c\u800c\u4e0d\u662f\u9700\u8981\u4f86\u56de\u95b1\u8b80\u3001\u53cd\u8986\u78ba\u8a8d\u3002\\n\\n<br />\\n\u7b46\u8005\u6700\u5e38\u7528\u5e7e\u500b\u65b9\u5f0f\uff0c\u63d0\u5347\u6587\u5b57\u7d44\u7e54\u80fd\u529b\u3002\\n\\n\u2705 \u4f7f\u7528\u77ed\u53e5 \u2013 \u53e5\u5b50\u8d8a\u9577\uff0c\u8b80\u8005\u8d8a\u5bb9\u6613\u8ff7\u5931\u3002\\n\\n\u2705 \u9069\u7576\u5206\u6bb5 \u2013 \u4e00\u6bb5\u8a71\u4e0d\u8981\u8d85\u904e 5 \u884c\uff0c\u8b93\u5167\u5bb9\u66f4\u6613\u8b80\u3002\\n\\n\u2705 \u52a0\u5165\u76ee\u9304\u548c\u5c0f\u6a19 \u2013 \u5e6b\u52a9\u8b80\u8005\u5feb\u901f\u627e\u5230\u8cc7\u8a0a\uff0c\u800c\u4e0d\u662f\u8b93\u4ed6\u5011\u5f9e\u982d\u8b80\u5230\u5c3e\u3002\\n\\n\u2705 \u52a0\u5165\u8868\u683c\u6216\u6bd4\u8f03 \u2013 \u8b93\u8b80\u8005\u53ef\u4ee5\u5feb\u901f\u6383\u63cf\uff0c\u800c\u4e0d\u5fc5\u95b1\u8b80\u5927\u6bb5\u6587\u5b57\u3002\\n\\n\u2705 \u5716\u6587\u4e26\u8302 \u2013 \u5716\u662f\u4eba\u985e\u7684\u597d\u670b\u53cb\uff0c\u5982\u679c\u4e00\u5f35\u5716\u80fd\u6bd4 500 \u5b57\u66f4\u6709\u6548\uff0c\u90a3\u4f7f\u7528\u5716\u8868\u4f86\u8f14\u52a9\u8aaa\u660e\uff0c\u80fd\u66f4\u6e05\u6670\u8868\u9054\u3002\\n\\n\u2705 \u89e3\u91cb\u540d\u8a5e\uff1a\u4e0d\u540c\u5c08\u696d\uff0c\u6709\u4e0d\u540c\u7684\u5c08\u6709\u540d\u8a5e\uff0c\u64b0\u5beb\u6587\u4ef6\u6642\uff0c\u8981\u5047\u8a2d\u8b80\u8005\u53ef\u80fd\u662f\u6c92\u6709\u76f8\u95dc\u7d93\u9a57\u7684\u4eba\uff0c\u9019\u4efd\u6587\u4ef6\u624d\u80fd\u6709\u6548\u7684\u88ab\u50b3\u627f\u548c\u4f7f\u7528\u3002\\n\\n\u2705 \u4fdd\u6301\u4e00\u81f4\u6027\uff1a\u6587\u4ef6\u7684\u683c\u5f0f\u3001\u8a9e\u8a00\u98a8\u683c\u3001\u8853\u8a9e\u61c9\u8a72\u7d71\u4e00\uff0c\u907f\u514d\u8b80\u8005\u6df7\u6dc6\u3002\\n\\n<br />\\n\\n## \u7d30\u7bc0\u7684\u9846\u7c92\u5ea6\uff1a\u5beb\u591a\u5c11\u624d\u525b\u525b\u597d\uff1f\\n\\n\u5f88\u591a\u4eba\u5beb\u6587\u4ef6\u6642\uff0c\u6703\u9047\u5230\u4e00\u500b\u554f\u984c\uff1a**\u300c\u9019\u500b\u7d30\u7bc0\u8981\u4e0d\u8981\u5beb\u9032\u53bb\uff1f\u300d**\\n\\n\u5982\u679c\u5beb\u5f97\u592a\u7c21\u55ae\uff0c\u8b80\u8005\u53ef\u80fd\u6703\u6709\u5f88\u591a\u7591\u554f\uff1b\u4f46\u5982\u679c\u5beb\u5f97\u592a\u8a73\u7d30\uff0c\u53c8\u6703\u8b93\u6587\u4ef6\u8b8a\u5f97\u5197\u9577\u96e3\u8b80\u3002\\n\\n\u7b46\u8005\u5728\u64b0\u5beb\u524d\uff0c\u6703\u5148\u78ba\u8a8d\u53ef\u80fd\u7684\u8b80\u8005\u6709\u8ab0\uff0c**\u91dd\u5c0d\u4e0d\u540c\u8b80\u8005\uff0c\u8abf\u6574\u7d30\u7bc0\u7a0b\u5ea6\uff0c**\\n\\n> \u6280\u8853\u4eba\u54e1\u9700\u8981\u66f4\u7d30\u7684\u6280\u8853\u7d30\u7bc0\uff0c\u800c\u696d\u52d9\u5718\u968a\u5247\u66f4\u95dc\u5fc3\u5546\u696d\u7b56\u7565\u548c\u6d41\u7a0b\u3002\\n\\n<br />\\n\\n## \u7d50\u8ad6\\n\\n\u9078\u64c7\u6587\u4ef6\u64b0\u5beb\u5de5\u5177\u6642\uff0c\u6700\u91cd\u8981\u7684\u4e0d\u662f\u5de5\u5177\u672c\u8eab\uff0c\u800c\u662f\u5982\u4f55\u4f7f\u7528\u5b83\u3002\\n\\n\u7576\u4f60\u80fd\u6e05\u695a\u8868\u9054\u908f\u8f2f\u3001\u7d44\u7e54\u689d\u7406\u5206\u660e\u7684\u5167\u5bb9\uff0c\u90a3\u9ebc\u4e0d\u7ba1\u4f7f\u7528\u54ea\u7a2e\u5de5\u5177\uff0c\u4f60\u7684\u6587\u4ef6\u90fd\u80fd\u8b93\u8b80\u8005\u5feb\u901f\u7406\u89e3\u3001\u63d0\u9ad8\u5de5\u4f5c\u6548\u7387\u3002\\n\\n\u6bcf\u500b\u5de5\u5177\u90fd\u6709\u5176\u512a\u52e2\uff0c\u4f46\u6838\u5fc3\u4ecd\u662f\u6587\u4ef6\u7d50\u69cb\u3001\u5167\u5bb9\u6e05\u6670\u5ea6\u3001\u4ee5\u53ca\u9069\u5408\u7684\u53d7\u773e\u3002\\n\\n\u53ea\u8981\u80fd\u63d0\u5347\u53ef\u8b80\u6027\uff0c\u8b93\u8b80\u8005\u66f4\u5feb\u627e\u5230\u8cc7\u8a0a\uff0c\u624d\u80fd\u771f\u6b63\u63d0\u9ad8\u5de5\u4f5c\u6548\u7387\uff01\\n\\n<br />\\n\\n\u5982\u679c\u8b80\u8005\u5c0d\u65bc\u64b0\u5beb\u5167\u5bb9\uff0c\u60f3\u9032\u4e00\u6b65\u8a0e\u8ad6\uff0c\u6b61\u8fce\u8207\u6211\u5011\u806f\u7e6b\uff01\ud83d\ude07\\n\\nEmail:\\n\\n> sadaionline.info@gmail.com"},{"id":"/2025/03/02/write-requirements-without-tech","metadata":{"permalink":"/blog/2025/03/02/write-requirements-without-tech","source":"@site/blog/2025-03-02-write-requirements-without-tech.md","title":"\u6c92\u6709\u6280\u8853\u80cc\u666f\uff1f\u5e36\u4f60\u5beb\u51fa\u6e05\u6670\u6613\u61c2\u7684\u9700\u6c42\u6587\u4ef6","description":"\u4e0d\u6703\u5beb\u9700\u6c42\u6587\u4ef6\uff08SRS\u3001BRD\u3001PRD\uff09\u55ce\uff1f\u9019\u7bc7\u6307\u5357\u9069\u5408\u7522\u54c1\u7d93\u7406\u3001\u5c08\u6848\u7d93\u7406\u3001\u696d\u52d9\u5206\u6790\u5e2b\uff0c\u6559\u4f60\u5982\u4f55\u7528\u6e05\u6670\u7d50\u69cb\u8207\u7bc4\u4f8b\u64b0\u5beb\u8b93\u5de5\u7a0b\u5e2b\u8b80\u5f97\u61c2\u7684\u9700\u6c42\u6587\u4ef6\uff0c\u78ba\u4fdd\u958b\u767c\u5718\u968a\u6e96\u78ba\u5be6\u73fe\u529f\u80fd\uff01","date":"2025-03-02T00:00:00.000Z","tags":[],"readingTime":6.25,"hasTruncateMarker":true,"authors":[{"name":"Lucy","title":"Co-Founder of SAD-AI","url":"https://github.com/sad-ai-online","imageURL":"https://avatars.githubusercontent.com/u/74943742?v=4","key":"lucy","page":null}],"frontMatter":{"date":"2025-03-02T00:00:00.000Z","title":"\u6c92\u6709\u6280\u8853\u80cc\u666f\uff1f\u5e36\u4f60\u5beb\u51fa\u6e05\u6670\u6613\u61c2\u7684\u9700\u6c42\u6587\u4ef6","authors":["lucy"],"description":"\u4e0d\u6703\u5beb\u9700\u6c42\u6587\u4ef6\uff08SRS\u3001BRD\u3001PRD\uff09\u55ce\uff1f\u9019\u7bc7\u6307\u5357\u9069\u5408\u7522\u54c1\u7d93\u7406\u3001\u5c08\u6848\u7d93\u7406\u3001\u696d\u52d9\u5206\u6790\u5e2b\uff0c\u6559\u4f60\u5982\u4f55\u7528\u6e05\u6670\u7d50\u69cb\u8207\u7bc4\u4f8b\u64b0\u5beb\u8b93\u5de5\u7a0b\u5e2b\u8b80\u5f97\u61c2\u7684\u9700\u6c42\u6587\u4ef6\uff0c\u78ba\u4fdd\u958b\u767c\u5718\u968a\u6e96\u78ba\u5be6\u73fe\u529f\u80fd\uff01","keywords":["\u5546\u696d\u9700\u6c42\u6587\u4ef6","\u7cfb\u7d71\u9700\u6c42\u6587\u4ef6","\u9700\u6c42\u64b0\u5beb","\u8edf\u9ad4\u958b\u767c","AI \u5de5\u5177","SAD-AI"]},"unlisted":false,"prevItem":{"title":"\u5225\u518d\u627e\u6587\u4ef6\u64b0\u5beb\u5de5\u5177\u4e86\uff1f\u5b78\u6703\u9019\u500b\u638c\u63e1\u6587\u4ef6\u6e05\u6670\u5ea6\uff01","permalink":"/blog/2025/03/08/optimal-docs-tool-choice"}},"content":"\u4e0d\u6703\u5beb\u9700\u6c42\u6587\u4ef6\uff08SRS\u3001BRD\u3001PRD\uff09\u55ce\uff1f\u9019\u7bc7\u6307\u5357\u9069\u5408\u7522\u54c1\u7d93\u7406\u3001\u5c08\u6848\u7d93\u7406\u3001\u696d\u52d9\u5206\u6790\u5e2b\uff0c\u6559\u4f60\u5982\u4f55\u7528\u6e05\u6670\u7d50\u69cb\u8207\u7bc4\u4f8b\u64b0\u5beb\u8b93\u5de5\u7a0b\u5e2b\u8b80\u5f97\u61c2\u7684\u9700\u6c42\u6587\u4ef6\uff0c\u78ba\u4fdd\u958b\u767c\u5718\u968a\u6e96\u78ba\u5be6\u73fe\u529f\u80fd\uff01\\n\\n\x3c!-- truncate --\x3e\\n\\n## \u524d\u8a00\\n\\n\u5728\u8edf\u9ad4\u958b\u767c\u5c08\u6848\u4e2d\uff0c\u9700\u6c42\u6587\u4ef6\uff08Software Requirements Specification, SRS\uff09\u662f\u9700\u6c42\u55ae\u4f4d\u8207\u958b\u767c\u5718\u968a\u4e2d\u4e0d\u53ef\u6216\u7f3a\u7684\u6a4b\u6a11\u3002\u5b83\u4e0d\u53ea\u662f\u958b\u767c\u5718\u968a\u7684\u4f9d\u64da\uff0c\u4e5f\u662f\u78ba\u4fdd\u7522\u54c1\u6700\u7d42\u7b26\u5408\u671f\u5f85\u7684\u95dc\u9375\u3002\\n\\n\u7136\u800c\uff0c\u5c0d\u65bc\u6c92\u6709\u6280\u8853\u80cc\u666f\u7684\u5c08\u6848\u7d93\u7406\u3001\u7522\u54c1\u7d93\u7406\u6216\u5546\u696d\u5206\u6790\u5e2b\u4f86\u8aaa\uff0c\u64b0\u5beb\u9700\u6c42\u6587\u4ef6\u53ef\u80fd\u6703\u8b93\u4eba\u611f\u5230\u982d\u75bc\u2014\u2014\u8981\u600e\u9ebc\u5beb\uff0c\u624d\u80fd\u8b93\u5de5\u7a0b\u5e2b\u8b80\u5f97\u61c2\uff1f\\n\\n\u5225\u64d4\u5fc3\uff01\u4f60\u4e0d\u9700\u8981\u6210\u70ba\u6280\u8853\u5c08\u5bb6\uff0c\u4e5f\u80fd\u5beb\u51fa\u6e05\u695a\u53c8\u5b8c\u6574\u7684\u9700\u6c42\u6587\u4ef6\u3002\\n\\n\u9019\u7bc7\u6587\u7ae0\u6703\u7528\u6700\u7c21\u55ae\u597d\u61c2\u7684\u65b9\u5f0f\uff0c\u5e36\u4f60\u4e00\u6b65\u6b65\u638c\u63e1\u64b0\u5beb\u6280\u5de7\uff0c\u8b93\u958b\u767c\u5718\u968a\u4e0d\u518d\u300c\u6191\u7a7a\u60f3\u50cf\u300d\uff0c\u800c\u662f\u771f\u6b63\u7406\u89e3\u4f60\u7684\u9700\u6c42\uff01\\n\\n## \u4ec0\u9ebc\u662f\u8edf\u9ad4\u9700\u6c42\u6587\u4ef6\uff08SRS\uff09\uff1f\\n\\nSRS \u5c31\u50cf\u662f\u300c\u7522\u54c1\u8aaa\u660e\u66f8 + \u898f\u683c\u8868\u300d\uff0c\u7528\u4f86\u6e05\u695a\u63cf\u8ff0\u7cfb\u7d71\u8a72\u505a\u4ec0\u9ebc\u3001\u4e0d\u8a72\u505a\u4ec0\u9ebc\uff0c\u4ee5\u53ca\u9810\u671f\u5982\u4f55\u904b\u4f5c\u3002\\n\\nSRS \u7684\u7528\u9014\u662f\uff1a\\n\\n- `\u8b93\u958b\u767c\u5718\u968a\u6e05\u695a\u9700\u6c42\uff0c\u5305\u542b\u4f7f\u7528\u6d41\u7a0b\u3001\u60c5\u5883\u3002`\\n- `\u63d0\u4f9b QA\uff08\u54c1\u8cea\u4fdd\u8b49\uff09\u6216\u8005\u9700\u6c42\u55ae\u4f4d\u7684\u7d93\u8fa6\uff0c\u80fd\u5920\u9a57\u8b49\u7d50\u679c\u662f\u5426\u5982\u9700\u6c42\u6587\u4ef6\u4e00\u81f4\u3002`\\n- `\u5e6b\u52a9\u5229\u5bb3\u95dc\u4fc2\u4eba\uff08Stakeholders\uff09\u8207\u958b\u767c\u5718\u968a\u5c0d\u7126\u9700\u6c42\uff0c\u907f\u514d\u56e0\u8cc7\u8a0a\u4e0d\u6e05\u9020\u6210\u7684\u958b\u767c\u932f\u8aa4\uff0c\u6e1b\u5c11\u5f8c\u7e8c\u958b\u767c\u904e\u7a0b\u7684\u8b8a\u66f4\u6210\u672c\u3002`\\n\\n\u900f\u904e\u9019\u4e9b\u65b9\u5f0f\uff0c\u8b93\u958b\u767c\u5718\u968a\u660e\u767d\uff1a\u300c\u4f7f\u7528\u8005\u9810\u671f\u7684\u7d50\u679c\u662f\u4ec0\u9ebc\uff1f\u8981\u770b\u5230\u54ea\u4e9b\u6210\u679c\uff1f\u300d\\n\\n\u5728\u5be6\u52d9\u7d93\u9a57\u4e2d\u6700\u5e38\u767c\u751f\u7684\u5e7e\u500b\u60c5\u5883\uff1a\\n\\n- \u9700\u6c42\u55ae\u4f4d\u6c92\u6709\u63d0\uff0c\u4f46\u5728 UAT \u968e\u6bb5\u9a57\u8b49\u6642\uff0c\u767c\u73fe\u9700\u8981\uff01\\n- \u4ee5\u70ba\u6c92\u6709\u5beb\uff0c\u5c31\u4e0d\u7528\u5be6\u505a\u529f\u80fd\u3002(\u696d\u52d9\u55ae\u4f4d\u7684\u4ee5\u70ba\uff0c\u548c\u958b\u767c\u5718\u7684\u4ee5\u70ba\uff0c\u901a\u5e38\u90fd\u4e0d\u592a\u4e00\u6a23)\\n- \u4ee5\u70ba\u5beb\u4e86\u696d\u52d9\u9700\u6c42\uff0c\u958b\u767c\u5718\u968a\u5c31\u80fd\u7406\u89e3\u3002(\u958b\u767c\u8005\u4e0d\u4e00\u5b9a\u719f\u6089\u5be6\u969b\u696d\u52d9\u9700\u6c42)\\n\\n\u7576\u4e0a\u8ff0\u767c\u751f\u6642\uff0c\u5982\u679c\u4e0d\u5f71\u97ff\u539f\u672c\u63d0\u51fa\u7684\u9700\u6c42\u6d41\u7a0b\uff0c\u901a\u5e38\u90fd\u597d\u8655\u7406\uff0c~~\u4e0d\u597d\u8655\u7406\u7684\uff0c\u901a\u5e38\u662f\u4eba~~\u3002\\n\\n\u4f46\u662f\u7576\u767c\u73fe\u662f\u300c\u9700\u6c42\u8b8a\u66f4\u300d\u5f71\u97ff\u73fe\u6709\u6d41\u7a0b\uff0c\u5c31\u5bb9\u6613\u5f71\u97ff\u958b\u767c\u6642\u7a0b\u3002\\n\\n\u6240\u4ee5\uff0c\u6587\u4ef6\u7684\u7528\u9014\u662f\u7528\u4f86\u5c0d\u7126\u5f7c\u6b64\u7684\u8a8d\u77e5\uff0c\u57f7\u884c\u524d\u9700\u6c42\u55ae\u4f4d\u548c\u958b\u767c\u55ae\u4f4d\uff0c\u90fd\u9700\u4e00\u8d77\u6aa2\u8996\u6587\u4ef6\u5167\u5bb9\uff0c\u4e0d\u6e05\u695a\u7684\u5730\u65b9\u5728\u6703\u8b70\u4e2d\u99ac\u4e0a\u78ba\u8a8d\u3002\\n\\n## \u70ba\u4ec0\u9ebc SRS \u9019\u9ebc\u91cd\u8981\uff1f\\n\\n\u8a31\u591a\u958b\u767c\u5c08\u6848\u5931\u6557\u7684\u539f\u56e0\uff0c\u5f80\u5f80\u4e0d\u662f\u6280\u8853\u554f\u984c\uff0c\u800c\u662f\u300c\u9700\u6c42\u6c92\u5c0d\u7126\u300d\u3002\\n\\n\u7576\u9700\u6c42\u4e0d\u660e\u78ba\uff0c\u958b\u767c\u4eba\u54e1\u53ea\u80fd\u9760\u731c\u6e2c\u4f86\u5b8c\u6210\u5de5\u4f5c\uff0c\u800c\u9019\u6a23\u7684\u7d50\u679c\u901a\u5e38\u8207\u696d\u52d9\u7aef\u7684\u671f\u5f85\u5927\u76f8\u9015\u5ead\u3002\\n\\n\u9700\u6c42\u4e0d\u6e05\u695a\uff0c\u6703\u5e36\u4f86\uff1a\\n\\n- `\u6e9d\u901a\u6210\u672c\u4e0a\u5347\uff1a\u958b\u767c\u5718\u968a\u9700\u8981\u53cd\u8986\u78ba\u8a8d\u9700\u6c42\uff0c\u62d6\u5ef6\u9032\u5ea6\u3002`\\n- `\u932f\u8aa4\u7684\u958b\u767c\u65b9\u5411\uff1a\u958b\u767c\u51fa\u4f86\u7684\u529f\u80fd\u53ef\u80fd\u4e0d\u7b26\u5408\u9700\u6c42\uff0c\u5c0e\u81f4\u91cd\u5de5\u3002`\\n- `\u6e2c\u8a66\u56f0\u96e3\uff1aQA \u7121\u6cd5\u78ba\u8a8d\u61c9\u8a72\u6e2c\u8a66\u54ea\u4e9b\u5167\u5bb9\u3002`\\n- `\u4f7f\u7528\u8005\u9ad4\u9a57\u4e0d\u4f73\uff1a\u6700\u7d42\u7522\u54c1\u53ef\u80fd\u7121\u6cd5\u89e3\u6c7a\u4f7f\u7528\u8005\u771f\u6b63\u7684\u75db\u9ede\u3002`\\n\\n\u4e00\u4efd\u6e05\u695a\u7684 SRS \u6587\u4ef6\uff0c\u80fd\u8b93\u958b\u767c\u904e\u7a0b\u66f4\u9806\u5229\uff0c\u907f\u514d\u4e0d\u5fc5\u8981\u7684\u6642\u9593\u8207\u8cc7\u6e90\u6d6a\u8cbb\u3002\\n\\n## \u64b0\u5beb SRS \u7684\u57fa\u672c\u67b6\u69cb\\n\\n\u4e0b\u5217\u662f\u666e\u904d\u696d\u52d9\u55ae\u4f4d\uff0c\u63d0\u6848\u7d66\u958b\u767c\u55ae\u4f4d\uff0c\u81f3\u5c11\u9700\u8981\u77e5\u9053\u7684\u8cc7\u8a0a\uff0c\u4ee5\u4fbf\u8a55\u4f30\u9700\u6c42\u5be6\u505a\u53ef\u884c\u6027\u3002\\n:::tip\\n\\n1. \u524d\u8a00\\n\\n   - \u76ee\u6a19\u8207\u80cc\u666f\\n   - \u6587\u4ef6\u7bc4\u570d\\n   - \u5b9a\u7fa9\u8207\u7e2e\u5beb\\n\\n2. \u7e3d\u9ad4\u63cf\u8ff0\\n\\n   - \u7522\u54c1\u529f\u80fd\u6982\u8ff0\\n   - \u7528\u6236\u89d2\u8272\u8207\u4f7f\u7528\u60c5\u5883\\n   - \u8a2d\u8a08\u9650\u5236\\n\\n3. \u5177\u9ad4\u9700\u6c42\\n\\n   - \u529f\u80fd\u6027\u9700\u6c42\\n   - \u975e\u529f\u80fd\u6027\u9700\u6c42\\n   - \u4f7f\u7528\u8005\u4ecb\u9762\u9700\u6c42\\n\\n4. \u5176\u4ed6\u8003\u91cf\\n   - \u7cfb\u7d71\u9700\u6c42\\n   - \u76f8\u5bb9\u6027\\n   - \u5b89\u5168\u6027\u8207\u96b1\u79c1\u8003\u91cf\\n\\n:::\\n\\n## \u64b0\u5beb SRS \u7684\u6280\u5de7\\n\\n### \u6d41\u7a0b\u5927\u65bc\u7d30\u7bc0\\n\\n\u6709\u53e5\u8a71\u9019\u9ebc\u8aaa\uff1a`\u842c\u4e8b\u8d77\u982d\u96e3\uff0c\u5148\u5f9e\u6d41\u7a0b\u8d77\u3002`\\n\\n\u7576\u63d0\u6848\u8005\u5c0d\u65bc\u6d41\u7a0b\u6709 100\uff05\u7684\u7406\u89e3\uff0c\u5c31\u8868\u793a\u638c\u63e1\u9700\u6c42\u6846\u67b6\uff0c\u8207\u958b\u767c\u5718\u968a\u8a0e\u8ad6\u6642\uff0c\u624d\u80fd\u6709\u6548\u6e9d\u901a\u548c\u8a0e\u8ad6\u5be6\u505a\u7d30\u7bc0\u3002\\n\\n### \u7528\u7c21\u55ae\u6e05\u695a\u7684\u8a9e\u8a00\u8868\u9054\u9700\u6c42\\n\\n\u8a31\u591a\u6280\u8853\u4eba\u54e1\u4e26\u4e0d\u719f\u6089\u696d\u52d9\u8853\u8a9e\uff0c\u56e0\u6b64\uff0c\u907f\u514d\u4f7f\u7528\u904e\u65bc\u5c08\u696d\u7684\u5546\u696d\u8853\u8a9e\uff0c\u800c\u61c9\u4f7f\u7528\u7c21\u55ae\u3001\u5177\u9ad4\u7684\u63cf\u8ff0\u3002\\n\\n\u53cd\u4e4b\uff0c\u6280\u8853\u4eba\u54e1\uff0c\u4e5f\u9700\u7528\u597d\u61c2\u7684\u63cf\u8ff0\u5c08\u6709\u540d\u8a5e\uff0c\u8b93\u696d\u52d9\u55ae\u4f4d\u7406\u89e3\u3002\\n\\n### \u82e5\u5c0d\u7cfb\u7d71\u6c92\u6709\u5b8c\u5168\u7684\u719f\u6089\uff0c\u4e0d\u5efa\u8b70\u5c0d\u958b\u767c\u5718\u968a\u4e0b\u6307\u5c0e\u68cb\\n\\n\u8853\u696d\u6709\u5c08\u653b\uff0c\u6280\u8853\u5718\u968a\u4e0d\u6703\u4ecb\u5165\u696d\u52d9\u5718\u968a\u5982\u4f55\u884c\u92b7\u3001\u5982\u4f55\u7372\u5ba2\uff0c\u66f4\u4e0d\u6703\u8981\u6c42\u696d\u52d9\u55ae\u4f4d\u8981\u7167\u4ec0\u9ebc\u65b9\u5f0f\u505a\u3002\\n\\n\u6bcf\u500b\u9818\u57df\u548c\u5718\u968a\u90fd\u6709\u5176\u5404\u81ea\u7684\u5c08\u696d\uff0c`\u5343\u842c\u4e0d\u8981\u4ee5\u81ea\u8eab\u7684\u8208\u8da3\u4f86\u6311\u6230\u5225\u4eba\u7684\u5c08\u696d`\u3002\\n\\n\u6240\u4ee5\u5728\u64b0\u5beb\u6587\u4ef6\u6642\uff0c\u53ea\u9700\u6e05\u695a\u63cf\u8ff0\u8981\u8003\u91cf OO \u4f7f\u7528\u60c5\u5883\uff0c\u4ee5\u7b26\u5408 OO \u9700\u6c42\u3002\\n\\n\u8981\u5982\u4f55\u5be6\u505a\uff0c\u6280\u8853\u5718\u968a\u6703\u4f9d\u7167\u73fe\u884c\u67b6\u69cb\u4e0b\u505a\u5c08\u696d\u8a55\u4f30\u3002\\n\\n### \u4f7f\u7528\u7bc4\u4f8b\u8207\u60c5\u5883\u8aaa\u660e\\n\\n\u7528\u7bc4\u4f8b\u8b93\u9700\u6c42\u66f4\u52a0\u5177\u8c61\u5316\u3002\u4f46\u5982\u679c\u662f\u53c3\u7167\u8a08\u6709\u5448\u73fe\u65b9\u5f0f\uff0c\u4e00\u6a23\u9700\u8981\u5beb`\u5448\u73fe\u65b9\u5f0f\u6cbf\u7528\u73fe\u884c\u8a2d\u8a08`\uff0c\u53ef\u4ee5\u5e6b\u52a9\u958b\u767c\u5718\u968a\u66f4\u5feb\u7406\u89e3\u9700\u6c42\u3002\\n\\n\u5047\u8a2d\u6b63\u5728\u64b0\u5beb\u4e00\u500b\u96fb\u5546\u7db2\u7ad9\u7684\u9700\u6c42\u6587\u4ef6\uff0c\u53ef\u4ee5\u9019\u6a23\u63cf\u8ff0\uff1a\\n\\n\u2705 \u4f8b\u5982\uff1a\\n\\n> \u7576\u7528\u6236\u5c07\u5546\u54c1\u52a0\u5165\u8cfc\u7269\u8eca\u5f8c\uff0c\u7cfb\u7d71\u61c9\u81ea\u52d5\u8a08\u7b97\u7e3d\u50f9\u683c\uff0c\u4e26\u986f\u793a\u904b\u8cbb\u3002\u82e5\u5546\u54c1\u5eab\u5b58\u4e0d\u8db3\uff0c\u5247\u61c9\u986f\u793a\u300c\u5eab\u5b58\u4e0d\u8db3\u300d\u7684\u63d0\u793a\u3002\\n\\n### \u660e\u78ba\u5b9a\u7fa9\u9a57\u6536\u6a19\u6e96\\n\\n\u958b\u767c\u4eba\u54e1\u9700\u8981\u77e5\u9053\u300c\u4ec0\u9ebc\u6a23\u7684\u7d50\u679c\u7b97\u662f\u7b26\u5408\u9700\u6c42\u7684\u300d\uff0c\u56e0\u6b64\u5728 SRS \u4e2d\u61c9\u5305\u542b\u660e\u78ba\u7684\u9a57\u6536\u6a19\u6e96\u3002\\n\\n\u2705 \u4f8b\u5982\uff1a\\n\\n> \u7576\u7528\u6236\u63d0\u4ea4\u8a02\u55ae\u5f8c\uff0c\u7cfb\u7d71\u61c9\u8df3\u51fa\u300c\u8a02\u55ae\u5df2\u63d0\u4ea4\u300d\u7684\u78ba\u8a8d\u8a0a\u606f\u3002\\n\\n## \u5982\u4f55\u8b93 SRS \u8b8a\u5f97\u66f4\u5bb9\u6613\u95b1\u8b80\uff1f\\n\\n\u5373\u4f7f\u9700\u6c42\u6587\u4ef6\u5beb\u5f97\u5f88\u5b8c\u6574\uff0c\u5982\u679c\u958b\u767c\u5718\u968a\u7121\u6cd5\u95b1\u8b80\uff0c\u4ecd\u7136\u7121\u6cd5\u767c\u63ee\u4f5c\u7528\u3002\\n\\n\u4ee5\u4e0b\u662f\u66f4\u5bb9\u6613\u88ab\u95b1\u8b80\u7684\u5c0f\u6487\u6b65\uff1a\\n\\n### \u4f7f\u7528\u8868\u683c\u8207\u6d41\u7a0b\u5716\\n\\n\u4eba\u5011\u559c\u6b61\u8996\u89ba\u5316\u7684\u8cc7\u8a0a\uff0c\u56e0\u6b64\uff0c\u4f7f\u7528\u8868\u683c\u3001\u6d41\u7a0b\u5716\u6216\u6642\u5e8f\u5716\uff08Sequence Diagram\uff09\u4f86\u5448\u73fe\u9700\u6c42\uff0c\u53ef\u4ee5\u5927\u5e45\u63d0\u5347\u53ef\u8b80\u6027\u3002\\n\\n| \u529f\u80fd       | \u689d\u4ef6                       | \u9810\u671f\u7d50\u679c                       |\\n| ---------- | -------------------------- | ------------------------------ |\\n| \u52a0\u5165\u8cfc\u7269\u8eca | \u7528\u6236\u9ede\u64ca\u300c\u52a0\u5165\u8cfc\u7269\u8eca\u300d\u6309\u9215 | \u5546\u54c1\u52a0\u5165\u8cfc\u7269\u8eca\uff0c\u986f\u793a\u78ba\u8a8d\u8a0a\u606f   |\\n| \u4ed8\u6b3e       | \u7528\u6236\u8f38\u5165\u4fe1\u7528\u5361\u8cc7\u8a0a\u4e26\u63d0\u4ea4   | \u7cfb\u7d71\u8655\u7406\u4ed8\u6b3e\uff0c\u986f\u793a\u8a02\u55ae\u78ba\u8a8d\u756b\u9762 |\\n\\n### \u5206\u6bb5\u64b0\u5beb\uff0c\u907f\u514d\u5197\u9577\\n\\n\u4eba\u5011\u7fd2\u6163\u5feb\u901f\u700f\u89bd\u91cd\u9ede\uff0c\u61c9\u907f\u514d\u5beb\u904e\u65bc\u5197\u9577\u7684\u6bb5\u843d\uff0c\u800c\u61c9\u5c07\u5167\u5bb9\u62c6\u5206\u6210\u8f03\u5c0f\u7684\u90e8\u5206\uff0c\u4e26\u4f7f\u7528\u6a19\u984c\u8207\u7de8\u865f\u4f86\u7d44\u7e54\u5167\u5bb9\u3002\\n\\n### \u8b93\u6280\u8853\u4eba\u54e1\u53c3\u8207\u9700\u6c42\u8a0e\u8ad6\\n\\n\u5728\u64b0\u5beb SRS \u4e4b\u524d\uff0c\u5148\u8207\u6280\u8853\u5718\u968a\u8a0e\u8ad6\u9700\u6c42\uff0c\u78ba\u4fdd\u4ed6\u5011\u80fd\u5920\u7406\u89e3\u696d\u52d9\u9700\u6c42\uff0c\u4e26\u63d0\u4f9b\u6280\u8853\u4e0a\u7684\u53ef\u884c\u6027\u5efa\u8b70\u3002\\n\\n## \u7d50\u8ad6\\n\\n\u6700\u5f8c\uff0c\u64b0\u5beb SRS \u5373\u4f7f\u6c92\u6709\u6280\u8853\u80cc\u666f\uff0c\u53ea\u8981\u638c\u63e1\u6e05\u695a\u7684\u8868\u9054\u696d\u52d9\u6d41\u7a0b\uff0c\u548c\u9810\u671f\u7d50\u679c\uff0c\u52a0\u4e0a\u4f7f\u7528\u7bc4\u4f8b\u8207\u5716\u8868\uff0c\u4ee5\u53ca\u8207\u958b\u767c\u5718\u968a\u4fdd\u6301\u826f\u597d\u7684\u6e9d\u901a\uff0c\u5c31\u5920\u8b93\u9700\u6c42\u6587\u4ef6\u767c\u63ee\u6700\u5927\u7684\u50f9\u503c\u3002\\n\\n\u5e0c\u671b\u9019\u7bc7\u6307\u5357\u80fd\u5920\u5e6b\u52a9\u4f60\u5beb\u51fa\u66f4\u6e05\u6670\u3001\u66f4\u5177\u53ef\u8b80\u6027\u7684\u9700\u6c42\u6587\u4ef6\uff0c\u8b93\u4f60\u7684\u958b\u767c\u5c08\u6848\u66f4\u52a0\u9806\u5229\uff01\\n\\n\u5982\u679c\u8b80\u8005\u5c0d\u65bc\u64b0\u5beb\u5167\u5bb9\uff0c\u60f3\u9032\u4e00\u6b65\u8a0e\u8ad6\uff0c\u6b61\u8fce\u8207\u6211\u5011\u806f\u7e6b\uff01\\n\\nEmail:\\n\\n> sadaionline.info@gmail.com"}]}}')}}]);